import Foundation
import RipulAgent

/// Single source of truth for Ripul integration constants in WAC.
///
/// The publishable site key is safe to embed in client builds — it is
/// origin-gated server-side via the key's `allowedOrigins` list. If the
/// API returns 403 "Origin not allowed", either change `originHeader`
/// here or update the key's allowlist on the server.
enum RipulConfig {
    /// Master feature flag for the in-app AI Agent.
    ///
    /// Backed by UserDefaults so users can opt in via Settings ▸ Beta
    /// Features ▸ "AI helper" (`BetaFeaturesView`). Off by default — the
    /// coordinator, panel view, native tools and the Ripul agent framework
    /// all remain in the build, just unreachable until the toggle is on.
    ///
    /// When `false`:
    /// - The "AI helper" card is never injected into the Home screen, so the
    ///   only user-facing entry point disappears (`HomeVC+API`).
    /// - The card's tap handler is a no-op as a defensive backstop
    ///   (`HomeVC+TableHandler`).
    /// - `TabBarVC.openAgent()` returns early, so the coordinator is never
    ///   instantiated even if invoked programmatically.
    ///
    /// Note: this gates the AI Agent UI only. Outbound shift-event telemetry
    /// is controlled separately by `RipulEventClient.isTransportEnabled`
    /// (currently hardcoded `false`).
    static let agentEnabledKey = "beta.aiAgentEnabled"
    static var isAgentEnabled: Bool { UserDefaults.standard.bool(forKey: agentEnabledKey) }

    /// Publishable site key (`pk_live_...`). Used by:
    /// - `WACAgentCoordinator` for `AgentConfiguration.siteKey`
    /// - `RipulEventClient` for the `X-Site-Key` header on `/v1/events`
    static let siteKey = "pk_live_qhzxe5zpbk2xb1v1lxb4z4sd"

    /// Origin sent on direct API calls. Must appear in the site key's
    /// `allowedOrigins` (or the allowlist must be `*`).
    static let originHeader = "https://wac-ios.app"

    /// CMS definition backing the WAC portal — the pages CmsRender draws
    /// natively. Matches the site key's linked `cmsDefinitionId`.
    static let cmsId = "cms_x5xpger1lv3j"

    /// Opaque portal credentials for CMS member mode: the SAME
    /// `secret`/`secret-id` headers every WAC API call carries. Ripul
    /// forwards them to WAC's `GET /api/v1/user`, so being logged into WAC
    /// IS being signed into the portal (member id `wac:<user.id>` — no
    /// second login). Returns nil when logged out; the renderer then shows
    /// its no-access state on invite-only portals.
    static func portalCredentials() -> [String: String]? {
        let secret = preference.secret
        let secretId = preference.secret_id
        guard !secret.isEmpty, !secretId.isEmpty else { return nil }
        // Mirror NetworkHelper.getHeader(): Ripul forwards the caller's
        // headers to WAC's validation endpoint, and that request must look
        // like a genuine app call — WAC's edge rejects bare credential-only
        // requests.
        var headers: [String: String] = [
            Key.secret: secret,
            Key.secret_id: secretId,
            Key.HTTP_LOCALE: "en",
            Key.HTTP_TIMEZONE: TimeZone.current.identifier,
        ]
        if let appVersion = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String {
            headers[Key.current_version] = appVersion
            headers[PARAMS.platform.rawValue] = Key.platform
        }
        return headers
    }

    /// The `CmsClientConfig` every CMS-portal surface uses: no Clerk token
    /// (WAC users aren't Clerk users) and the opaque credential provider that
    /// proves WAC login. One factory so `CmsPageView` and the sidebar menu
    /// resolver stay in lock-step.
    static func portalClientConfig() -> CmsClientConfig {
        CmsClientConfig(
            getToken: { nil },
            portalCredentialProvider: { portalCredentials() }
        )
    }
}
import UIKit
import SwiftUI
import RipulAgent

/// Host side of the CMS↔embedder sidebar-merge protocol.
///
/// `CmsPortalMenuResolver` (SDK) contributes the portal's role-filtered nav
/// items; this type caches them and renders them as a native section inside
/// WAC's slide-out sidebar (`RecordMenu`). The section only appears when the
/// signed-in WAC user is a portal member — the resolver returns `.none` for
/// non-members and blocked users, so the gate is automatic.
///
/// The menu is cached across sidebar opens (the sidebar is rebuilt on every
/// open) and refreshed in the background so membership/role changes propagate.
enum RipulPortalSidebar {
    /// Last resolved contribution. `nil` = not yet resolved this launch.
    private(set) static var cachedMenu: CmsPortalMenu?

    /// Posted on the main thread when `cachedMenu` changes, so an already-open
    /// sidebar can insert the section live once the first resolve lands.
    static let didUpdate = Notification.Name("RipulPortalSidebar.didUpdate")

    /// Kick off a background resolve. Cheap to call on every sidebar open —
    /// it reuses the same site-key validate + `/me` calls the renderer makes.
    static func refresh() {
        guard RipulConfig.portalCredentials() != nil else {
            // Logged out → definitively no section.
            if cachedMenu?.isMember != false {
                cachedMenu = .none
                NotificationCenter.default.post(name: didUpdate, object: nil)
            }
            return
        }
        Task {
            let menu = await CmsPortalMenuResolver.resolve(
                cmsId: RipulConfig.cmsId,
                siteKey: RipulConfig.siteKey,
                clientConfig: RipulConfig.portalClientConfig()
            )
            await MainActor.run {
                cachedMenu = menu
                NotificationCenter.default.post(name: didUpdate, object: nil)
            }
        }
    }

    /// Depth-first flatten to the navigable leaves — the host renders a flat
    /// section of destinations (the full tree still lives inside the portal).
    static func navigableLeaves() -> [CmsPortalMenuItem] {
        guard let menu = cachedMenu, menu.isMember else { return [] }
        var out: [CmsPortalMenuItem] = []
        func walk(_ items: [CmsPortalMenuItem]) {
            for it in items {
                if it.pageSlug != nil || it.url != nil { out.append(it) }
                walk(it.children)
            }
        }
        walk(menu.items)
        return out
    }
}

/// A single CMS portal page, hosted natively. Opening any merged sidebar row
/// pushes one of these at the row's page.
struct RipulPortalPage: View {
    let pageSlug: String?
    var body: some View {
        CmsPageView(
            cmsId: RipulConfig.cmsId,
            pageSlug: pageSlug,
            clientConfig: RipulConfig.portalClientConfig(),
            visitorSiteKey: RipulConfig.siteKey,
            // Host owns navigation (the sidebar's Workplace section), so the
            // CMS must not claim the screen edges — otherwise its drawer
            // hijacks the left edge and blocks both the nav back-swipe and
            // WAC's own slide-out sidebar.
            edgeSwipeEnabled: false
        )
    }
}

/// Builds the native "Workplace" section for the slide-out sidebar from the
/// resolved menu items. Kept UIKit so it drops straight into `RecordMenu`'s
/// scroll content alongside the calendar/jobs/status boxes.
enum RipulPortalSidebarSection {
    /// The section header caption. Static — the portal name isn't in the
    /// membership response; "WAC Business" is the authored label.
    static let title = "WAC Business"

    /// Build the section, or nil when there's nothing to contribute (not a
    /// member / no reachable items). Returns the container plus its header
    /// label so the host can align the header's leading with its other
    /// section headers. `headerFont`/`headerColor` are copied from a sibling
    /// header so the caption matches exactly (same face, size, tint).
    /// `onOpen` fires with the tapped item's page slug + label.
    static func make(
        headerFont: UIFont?,
        headerColor: UIColor?,
        onOpen: @escaping (_ slug: String?, _ title: String) -> Void
    ) -> (container: UIView, header: UILabel)? {
        let leaves = RipulPortalSidebar.navigableLeaves()
        guard !leaves.isEmpty else { return nil }

        let container = UIView()
        container.backgroundColor = .clear

        let header = UILabel()
        header.translatesAutoresizingMaskIntoConstraints = false
        header.text = title
        header.font = headerFont ?? UIFont.getThemeFont(fontWight: .bold, size: 18)
        header.textColor = headerColor ?? Color.Semantic.textPrimary
        container.addSubview(header)

        let stack = UIStackView()
        stack.translatesAutoresizingMaskIntoConstraints = false
        stack.axis = .vertical
        stack.spacing = 2
        container.addSubview(stack)

        for item in leaves {
            stack.addArrangedSubview(rowButton(item: item, onOpen: onOpen))
        }

        // Fallback header leading — the host overrides it with a required
        // constraint aligning to its sibling section headers.
        let headerLeading = header.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 16)
        headerLeading.priority = .defaultLow

        NSLayoutConstraint.activate([
            header.topAnchor.constraint(equalTo: container.topAnchor),
            headerLeading,
            header.trailingAnchor.constraint(lessThanOrEqualTo: container.trailingAnchor, constant: -16),

            stack.topAnchor.constraint(equalTo: header.bottomAnchor, constant: 8),
            stack.leadingAnchor.constraint(equalTo: container.leadingAnchor),
            stack.trailingAnchor.constraint(equalTo: container.trailingAnchor),
            stack.bottomAnchor.constraint(equalTo: container.bottomAnchor),
        ])
        return (container, header)
    }

