// MARK: - Ripul dev console (developer session list + host Mac)

/// Debug · the native Ripul DEVELOPER console (SDK `RipulAgentConsole`): sign into
/// your OWN Ripul account (Clerk), list your paired host Macs, and drive Claude on
/// one — from inside WAC. This is a developer tool, distinct from the end-user AI
/// helper. Isolated from WAC's end-user portal session via a private cache suite
/// (`com.wac.ripuldev`) + a dedicated web data store, and NO WAC site key (so the
/// embedded web app runs as the developer's own Ripul/Clerk identity).
/// The floating bubble + overlay window itself is the SDK's
/// `RipulDevAssistantOverlay` (Sessions/RipulDevAssistantOverlay.swift) - the
/// classes that used to live here were deleted in the lift.

@available(iOS 26.0, *)
enum RipulDevConsoleConfig {
    /// Isolated cache suite — the dev console's list state never collides with
    /// WAC's own UserDefaults.
    private static let cache = UserDefaultsSessionCache(suiteName: "com.wac.ripuldev")
    /// Dedicated, persistent web data store keyed by a fixed identifier so the
    /// developer's Clerk cookies survive relaunches and stay isolated from any
    /// WAC web content.
    private static let dataStore = WKWebsiteDataStore(
        forIdentifier: UUID(uuidString: "D3F00DEC-0000-0000-0000-00000000C0DE")!
    )
    static let shared = RipulSessionsConfiguration(
        cache: cache,
        siteKey: "pk_live_4w3sb5vg9kci3l5i2fey8zyt",
        websiteDataStore: dataStore,
        // WAC's ONE tool registry (native-tool-registry phase 1): the console's
        // .developer channel exposes its developer-tagged entries (the theme
        // write-tools, so the agent driving from here can change the running
        // app instead of only observing it — the console itself supplies the
        // read tools), and the Tool Collections editor reads the same registry
        // for the end-user surface. The old devTools/endUserTools double
        // declaration is gone: register once, tagged, consumed everywhere.
        registry: WACNativeTools.registry,
        // Puts "Solutions" in the console's sessions menu — collections,
        // contexts, the model catalog, macros. The SDK moved Solutions out of
        // the sessions list and onto the first-party app's sidebar, which WAC
        // does not have, so without this the console has no route to it at all.
        //
        // The screen hands back its own Clerk token provider: this config is a
        // static `let`, built long before RipulAgentConsole creates the auth
        // store the console signs into.
        //
        // showsSiteKeyAdmin stays off (default) — a developer curates contexts
        // and collections; binding them to site keys is a platform-admin act
        // performed from the Ripul app, and the API gates it regardless.
        // buildsApp stays nil: WAC publishes its OTA builds to its own R2
        // bucket (scripts/deploy-wac-ota.sh), not to the Ripul hosted feed, so
        // the Builds row would have nothing to list.
        solutionManagement: { tokenProvider in
            // The same sign-in lets WAC's theme tools publish the server theme (WACServerTheme).
            MainActor.assumeIsolated { WACServerTheme.tokenProvider = tokenProvider }
            return RipulSolutionManagement(
                registry: WACNativeTools.registry,
                baseURL: AgentConfiguration.defaultBaseURL,
                tokenProvider: tokenProvider
            )
        }
    )
}

