import type { CmsDefinition } from '../cmsDefinitions/types';

/** Tenant-authored mapping; no WAC column names belong in the runtime. */
export interface EmbeddedAgentsConfig {
  enabled: boolean;
  /** Change when changing the mapping's meaning. Existing bindings never migrate. */
  profileVersion: number;
  /** Optional staged rollout; an empty list enables no companies. */
  allowedOrganisationIds?: string[];
  /** Explicit pilot opt-in. Only named employment bindings can run AI. */
  runner?: { enabled: boolean; allowedBindingKeys: string[] };
  /** Verified CMS membership supplies the role/company. One nominee per company. */
  management?: {
    siteKeyId: string;
    organisationField: string;
    nameField: string;
    nominees: Record<string, string>;
  };
  binding: {
    table: string;
    idColumn: string;
    keyColumn: string;
    organisationColumn: string;
    statusColumn: string;
    /** Optional presentation only; never used to establish or change identity. */
    displayNameColumn?: string;
    activeValues: string[];
    formerValues: string[];
  };
}

export class EmbeddedAgentError extends Error {
  constructor(public status: number, message: string) { super(message); }
}

/** Name presentation may change without invalidating established job identities. */
export function embeddedIdentityUpdateAllowed(previous: EmbeddedAgentsConfig | undefined, next: EmbeddedAgentsConfig): boolean {
  if (!previous) return true;
  if (next.profileVersion < previous.profileVersion) return false;
  const identity = (b: EmbeddedAgentsConfig['binding']) => JSON.stringify([
    b.table, b.idColumn, b.keyColumn, b.organisationColumn, b.statusColumn, b.activeValues, b.formerValues,
  ]);
  return identity(previous.binding) === identity(next.binding) || next.profileVersion > previous.profileVersion;
}

export function validateEmbeddedAgents(raw: unknown, cms: Pick<CmsDefinition, 'tables' | 'connections'>): string | null {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return 'embeddedAgents must be an object.';
  const c = raw as Record<string, unknown>;
  if (Object.keys(c).some(k => !['enabled', 'profileVersion', 'binding', 'allowedOrganisationIds', 'runner', 'management'].includes(k))) return 'Unknown embeddedAgents setting.';
  if (c.management !== undefined) {
    const m = c.management as EmbeddedAgentsConfig['management'];
    if (!m || typeof m !== 'object' || Array.isArray(m) ||
      Object.keys(m).some(k => !['siteKeyId', 'organisationField', 'nameField', 'nominees'].includes(k)) ||
      typeof m.siteKeyId !== 'string' || !/^sk_[\w-]+$/.test(m.siteKeyId) ||
      ![m.organisationField, m.nameField].every(v => typeof v === 'string' && /^[a-zA-Z][\w]{0,63}$/.test(v)) ||
      !m.nominees || typeof m.nominees !== 'object' || Array.isArray(m.nominees) ||
      Object.keys(m.nominees).length > 1000 ||
      Object.entries(m.nominees).some(([org, email]) => !org.trim() || org.length > 200 ||
        typeof email !== 'string' || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)))
      return 'management needs a portal site, membership field mappings and one manager email per company.';
  }
  if (c.runner !== undefined) {
    const r = c.runner as EmbeddedAgentsConfig['runner'];
    if (!r || typeof r !== 'object' || Object.keys(r).some(k => !['enabled', 'allowedBindingKeys'].includes(k)) ||
      typeof r.enabled !== 'boolean' || !Array.isArray(r.allowedBindingKeys) || r.allowedBindingKeys.length > 100 ||
      r.allowedBindingKeys.some(k => typeof k !== 'string' || !k.trim() || k.length > 200))
      return 'runner needs enabled and an explicit allowedBindingKeys pilot list.';
  }
  if (typeof c.enabled !== 'boolean' || !Number.isSafeInteger(c.profileVersion) || Number(c.profileVersion) < 1)
    return 'embeddedAgents needs enabled and a positive integer profileVersion.';
  if (c.allowedOrganisationIds !== undefined && (!Array.isArray(c.allowedOrganisationIds) || c.allowedOrganisationIds.length > 1000 || c.allowedOrganisationIds.some(v => typeof v !== 'string' || !v.trim() || v.length > 200)))
    return 'allowedOrganisationIds must be a list of company identifiers.';
  if (!c.binding || typeof c.binding !== 'object' || Array.isArray(c.binding)) return 'A binding mapping is required.';
  const b = c.binding as Record<string, unknown>;
  if (Object.keys(b).some(k => !['table', 'idColumn', 'keyColumn', 'organisationColumn', 'statusColumn', 'displayNameColumn', 'activeValues', 'formerValues'].includes(k)))
    return 'Unknown binding setting.';
  const table = cms.tables?.find(t => t.slug === b.table);
  const connection = cms.connections?.find(c => c.id === table?.connectionId);
  // First adapter: tenant-owned D1 tables. Remote/query adapters can implement the same contract later.
  if (!table || connection?.source !== 'd1' || connection.d1?.bindingName !== 'DB')
    return 'The binding table must use the CMS DB D1 connection.';
  const columns = ['idColumn', 'keyColumn', 'organisationColumn', 'statusColumn'].map(k => b[k]);
  if (columns.some(c => typeof c !== 'string' || !table.columns.some(t => t.name === c)) || new Set(columns).size !== 4)
    return 'Binding columns must name four distinct columns in the configured table.';
  if (b.displayNameColumn !== undefined && (typeof b.displayNameColumn !== 'string' ||
    !table.columns.some(t => t.name === b.displayNameColumn && t.type === 'string') ||
    columns.includes(b.displayNameColumn)))
    return 'displayNameColumn must name a separate text column in the binding table.';
  for (const key of ['activeValues', 'formerValues']) {
    const values = b[key];
    if (!Array.isArray(values) || values.length > 20 || values.some(v => typeof v !== 'string' || !v.trim() || v.length > 100) || new Set(values).size !== values.length)
      return `${key} must contain distinct nonempty status strings.`;
  }
  const active = b.activeValues as string[], former = b.formerValues as string[];
  if (!active.length || active.some(v => former.includes(v))) return 'Active and former statuses must not overlap; at least one active status is required.';
  return null;
}

export function configured(cms: CmsDefinition): EmbeddedAgentsConfig {
  const config = cms.embeddedAgents;
  if (!config?.enabled) throw new EmbeddedAgentError(404, 'Authenticated agents are not enabled for this site.');
  if (validateEmbeddedAgents(config, cms)) throw new EmbeddedAgentError(409, 'The identity mapping needs administrator attention.');
  return config;
}

export interface BindingRecord {
  recordId: string;
  bindingKey: string;
  organisationId: string;
  status: 'active' | 'former';
}

const quoted = (name: string) => `"${name.replace(/"/g, '""')}"`;

/** This narrow bootstrap read returns no employee data beyond the binding contract. */
export async function findBinding(db: D1Database, cms: CmsDefinition, key: string): Promise<BindingRecord> {
  const c = configured(cms), b = c.binding;
  const table = cms.tables!.find(t => t.slug === b.table)!;
  const rows = await db.prepare(`SELECT ${quoted(b.idColumn)} AS recordId, ${quoted(b.keyColumn)} AS bindingKey,
    ${quoted(b.organisationColumn)} AS organisationId, ${quoted(b.statusColumn)} AS status
    FROM ${quoted(table.physicalName ?? table.slug)} WHERE ${quoted(b.keyColumn)} = ? LIMIT 2`).bind(key).all<Record<string, unknown>>();
  if (rows.results.length !== 1) throw new EmbeddedAgentError(404, 'This code cannot be claimed.');
  const row = rows.results[0];
  const scalar = (v: unknown) => typeof v === 'string' ? v : typeof v === 'number' && Number.isSafeInteger(v) ? String(v) : '';
  const recordId = scalar(row.recordId), organisationId = scalar(row.organisationId);
  if (!recordId || !organisationId || typeof row.bindingKey !== 'string' || row.bindingKey !== key)
    throw new EmbeddedAgentError(409, 'The identity mapping returned an invalid relationship.');
  const status = b.activeValues.includes(String(row.status)) ? 'active' : b.formerValues.includes(String(row.status)) ? 'former' : null;
  if (!status) throw new EmbeddedAgentError(404, 'This code cannot be claimed.');
  requireOrganisation(c, organisationId);
  return { recordId, bindingKey: key, organisationId, status };
}

export function requireOrganisation(config: EmbeddedAgentsConfig, organisationId: string): void {
  if (config.allowedOrganisationIds && !config.allowedOrganisationIds.includes(organisationId))
    throw new EmbeddedAgentError(403, 'Conversations are not enabled for this company.');
}

