/** A separate, fail-closed auth lane. These credentials never enter general CMS/relay APIs. */
import type { Env } from '../types';
import { getSiteKeyById, getSiteKeyByPublishableKey, getSiteKeyOwner } from '../siteKeys/storage';
import { isOriginAllowed } from '../siteKeys/validation';
import { resolveOpaquePrincipal } from '../siteKeys/opaquePortalAuth';
import { getCmsDefinitionById } from '../cmsDefinitions/storage';
import { readJson } from '../cmsIntegrations/policy';
import { allowWithin } from '../auth/rateLimit';
import { configured, findBinding, EmbeddedAgentError } from './config';
import { appendMessage, claimCode, createConversation, createSession, digest, endSession, listClaims, listConversations, readConversation, readMessages, sessionIdentity } from './store';
import { activeIssue, enqueueIssue } from './issues';

export const EMBEDDED_AGENT_PATH = /^\/v1\/embedded-agents\/([^/]+)\/(session|claims|conversations|availability)(?:\/(ecv_[0-9a-f-]{36})(?:\/(messages))?)?$/;
const reply = (data: unknown, status = 200) => new Response(JSON.stringify(data), {
  status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
});

function fields(raw: unknown, names: string[]): Record<string, string> {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw) || Object.keys(raw).length !== names.length ||
    Object.keys(raw).some(k => !names.includes(k))) throw new EmbeddedAgentError(400, 'Unexpected request fields.');
  const out: Record<string, string> = {};
  for (const name of names) {
    const value = (raw as Record<string, unknown>)[name];
    if (typeof value !== 'string' || !value.trim() || value.length > (name === 'content' ? 8000 : 200))
      throw new EmbeddedAgentError(400, `Invalid ${name}.`);
    out[name] = value;
  }
  return out;
}

export async function handleEmbeddedAgents(request: Request, env: Env, match: RegExpMatchArray): Promise<Response> {
  let allowedOrigin: string | null = null;
  const finish = (response: Response) => {
    if (allowedOrigin) {
      response.headers.set('Access-Control-Allow-Origin', allowedOrigin);
      response.headers.set('Vary', 'Origin');
    }
    return response;
  };
  try {
    const [, siteKeyId, part, conversationId, messages] = match;
    const site = siteKeyId.startsWith('pk_') ? await getSiteKeyByPublishableKey(siteKeyId, env) : await getSiteKeyById(siteKeyId, env);
    if (!site?.enabled) throw new EmbeddedAgentError(404, 'Site not found.');
    const origin = request.headers.get('Origin');
    if (!origin || !isOriginAllowed(origin, site.allowedOrigins)) throw new EmbeddedAgentError(403, 'Origin is not allowed.');
    allowedOrigin = origin;
    const config = site.portalAuthOpaque ?? (site.portalAuth?.provider === 'opaque' ? site.portalAuth : undefined);
    // Do not guess a provider, downgrade to anonymous, or merge by email.
    if (!config) throw new EmbeddedAgentError(409, 'This site needs a supported customer authentication provider.');
    const cmsId = site.delegateCmsDefinitionTo
      ? (await getSiteKeyById(site.delegateCmsDefinitionTo, env))?.cmsDefinitionId : site.cmsDefinitionId;
    const cms = cmsId ? await getCmsDefinitionById(cmsId, 'default', env) : null;
    if (!cms) throw new EmbeddedAgentError(404, 'Site definition not found.');
    configured(cms);
    if (request.method === 'OPTIONS') {
      const response = reply(null, 200);
      response.headers.set('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
      response.headers.set('Access-Control-Allow-Headers', ['Authorization', 'Content-Type', ...config.credentialHeaders, 'locale', 'timezone', 'current-version', 'platform'].join(', '));
      response.headers.set('Access-Control-Max-Age', '300');
      return finish(response);
    }
    // Fingerprint provider semantics including validation origin: a configuration change invalidates old sessions.
    const issuer = await digest(JSON.stringify([site.id, config.originId, cms.origins?.find(o => o.id === config.originId)?.baseUrl, config.path, config.principalIdPath, config.subPrefix ?? 'opaque']));
    if (part === 'session' && !conversationId && request.method === 'POST') {
      if (!(await allowWithin(env, `embedded-login:${site.id}:${request.headers.get('CF-Connecting-IP') ?? 'unknown'}`, 30, 60)))
        throw new EmbeddedAgentError(429, 'Too many sign-in attempts.');
      const principal = await resolveOpaquePrincipal(request, config, site, env);
      if (!principal) throw new EmbeddedAgentError(401, 'Sign in to the customer app.');
      const owner = await getSiteKeyOwner(site.id, `${config.subPrefix ?? 'opaque'}:${principal.id}`, env);
      if (owner?.status === 'blocked') throw new EmbeddedAgentError(403, 'Account access is blocked.');
      return finish(reply(await createSession(env.DB, { cmsId: cms.id, siteKeyId: site.id, issuer, subject: principal.id }), 201));
    }
    const token = request.headers.get('Authorization')?.match(/^Bearer ([a-f0-9]{64})$/)?.[1] ?? '';
    const identity = await sessionIdentity(env.DB, token, cms.id, site.id, issuer);
    const owner = await getSiteKeyOwner(site.id, `${config.subPrefix ?? 'opaque'}:${identity.subject}`, env);
    if (owner?.status === 'blocked') throw new EmbeddedAgentError(403, 'Account access is blocked.');
    if (part === 'session' && request.method === 'DELETE' && !conversationId) {
      await endSession(env.DB, token);
      return finish(reply({ signedOut: true }));
    }
    if (part === 'availability' && request.method === 'POST' && !conversationId) {
      if (!(await allowWithin(env, `embedded-availability:${site.id}:${await digest(identity.subject)}`, 60, 600)))
        throw new EmbeddedAgentError(429, 'Too many availability checks.');
      const body = fields(await readJson(request, 1024), ['code']);
      try {
        await findBinding(env.DB, cms, body.code);
        return finish(reply({ enabled: true }));
      } catch (error) {
        if (error instanceof EmbeddedAgentError && [403, 404].includes(error.status)) return finish(reply({ enabled: false }));
        throw error;
      }
    }
    if (part === 'claims' && !conversationId) {
      if (request.method === 'GET') return finish(reply({ claims: await listClaims(env.DB, cms, identity) }));
      if (request.method === 'POST') {
        if (!(await allowWithin(env, `embedded-claim:${site.id}:${await digest(identity.subject)}`, 10, 600)))
          throw new EmbeddedAgentError(429, 'Too many code attempts.');
        const body = fields(await readJson(request, 1024), ['code']);
        return finish(reply({ claim: await claimCode(env.DB, cms, identity, body.code) }));
      }
    }
    if (part === 'conversations') {
      if (request.method === 'GET' && !conversationId) {
        const claimId = new URL(request.url).searchParams.get('claimId');
        if (!claimId || claimId.length > 200) throw new EmbeddedAgentError(400, 'A claimId is required.');
        return finish(reply({ conversations: await listConversations(env.DB, cms, identity, claimId) }));
      }
      if (request.method === 'POST' && !conversationId) {
        if (!(await allowWithin(env, `embedded-new:${site.id}:${await digest(identity.subject)}`, 30, 3600)))
          throw new EmbeddedAgentError(429, 'Too many new conversations.');
        const body = fields(await readJson(request, 1024), ['claimId']);
        return finish(reply({ conversation: await createConversation(env.DB, cms, identity, body.claimId) }, 201));
      }
      if (conversationId && request.method === 'GET') return finish(reply(messages
        ? { messages: await readMessages(env.DB, cms, identity, conversationId) }
        : { conversation: await readConversation(env.DB, cms, identity, conversationId) }));
      if (conversationId && messages && request.method === 'POST') {
        if (!(await allowWithin(env, `embedded-message:${site.id}:${await digest(identity.subject)}`, 120, 60)))
          throw new EmbeddedAgentError(429, 'Too many messages.');
        const body = fields(await readJson(request, 12000), ['id', 'content']);
        await appendMessage(env.DB, cms, identity, conversationId, body.id, body.content);
        const issue = await env.DB.prepare('SELECT conversation_id FROM embedded_agent_issues WHERE conversation_id = ?').bind(conversationId).first();
        if (issue) {
          const active = await activeIssue(env, conversationId);
          if (active.issue.status === 'manager_joined') return finish(reply({ accepted: true, runnerStatus: 'manager_joined' }));
          await enqueueIssue(env, conversationId, body.id);
          return finish(reply({ accepted: true, runnerStatus: 'queued' }));
        }
        return finish(reply({ accepted: true, runnerStatus: 'not_enabled' }));
      }
    }
    return finish(reply({ error: 'Method not allowed.' }, 405));
  } catch (error) {
    if (error instanceof EmbeddedAgentError) return finish(reply({ error: error.message }, error.status));
    const status = (error as { status?: unknown })?.status;
    if (typeof status === 'number' && status >= 400 && status < 500) return finish(reply({ error: 'Invalid request body.' }, status));
    console.error('[embedded-agents] Request failed', error instanceof Error ? error.name : 'unknown');
    return finish(reply({ error: 'The embedded agent request could not be completed.' }, 500));
  }
}

