import type { Env } from '../types';
import type { CmsDefinition } from '../cmsDefinitions/types';
import { getSiteKeyOwner } from '../siteKeys/storage';
import { getCmsDefinitionById } from '../cmsDefinitions/storage';
import { resolveMemberContext } from '../cmsDefinitions/handlers';
import { resolvePortalIdentity, type AuthenticatedPortalCaller } from '../siteKeys/portalIdentity';
import { configured, EmbeddedAgentError, requireOrganisation } from './config';
import { readJson, IntegrationError } from '../cmsIntegrations/policy';
import { jsonResponse } from '../utils/responses';
import { fetchClerkUser, verifiedEmails } from '../auth/clerk';
import { allowWithin } from '../auth/rateLimit';
