/**
 * Handle GET /v1/site-key/me — the authenticated user's membership on a site
 * key, used by the portal for role-based page visibility. Resolves the owner
 * row by the verified email claim (BYOA sub is tenant-scoped) and falls back
 * to the user id. When there's no binding, attempts a JIT-bind from the site's
 * directory table. Returns isMember:false when neither resolves.
 */
export async function handleSiteKeyMe(
  siteKeyId: string,
  ctx: AuthContext,
  env: Env
): Promise<Response> {
  const sk = await getSiteKeyById(siteKeyId, env);
  let owner = ctx.email ? await getSiteKeyOwnerByEmail(siteKeyId, ctx.email, env) : null;
  if (!owner && ctx.userId) {
    owner = await getSiteKeyOwner(siteKeyId, ctx.userId, env);
  }
  if (!owner && ctx.email && sk && membershipPolicyOf(sk) !== 'invite-only') {
    owner = await jitBindFromDirectory(siteKeyId, ctx, env);
  }
  // Blocked members are non-members everywhere; the row survives so the admin
  // can reinstate (and so open-enrollment re-registration can't resurrect them).
  if (owner?.status === 'blocked') owner = null;

  const cms = owner && sk ? await resolveCmsForSiteKey(sk, env) : null;

  // An authoritative directory decides everyone below site admin, on every
  // sign-in: removed or deactivated in the directory means not a member, and a
  // role changed there is applied (and saved, so the admin screens agree).
  if (owner && cms?.directoryTable?.authoritative) {
    const row = await readDirectoryRow(cms, siteKeyId, ctx.email ?? owner.email, env);
    const verdict = directoryVerdict(cms.directoryTable, owner, row);
    if (verdict.governed) {
      if (!verdict.owner) {
        console.log(`[directory] not a member: no active directory row with a role email=${ctx.email ?? owner.email ?? '∅'} siteKey=${siteKeyId}`);
      } else if (verdict.owner.role !== owner.role) {
        await updateSiteKeyOwnerRole(siteKeyId, owner.userId, verdict.owner.role, env);
        console.log(`[directory] role ${owner.role} → ${verdict.owner.role} from the directory email=${ctx.email ?? owner.email ?? '∅'} siteKey=${siteKeyId}`);
      }
      owner = verdict.owner;
    }
  }

  // Delegated-design capability: a member whose role is listed in the portal
  // definition's `designRoles` may enter design mode. Resolved here so the
  // client gate has a single server-authored signal — the design write
  // endpoint (`PATCH /v1/cms-definitions/:id/design`) re-checks independently.
  const canDesign = !!(owner && cms?.designRoles?.length && cms.designRoles.includes(owner.role));

  const body: SiteKeyMeResponse = owner
    ? {
        isMember: true,
        role: owner.role,
        customProperties: owner.customProperties,
        email: owner.email ?? ctx.email,
        canDesign,
      }
    : { isMember: false, email: ctx.email };
  return new Response(JSON.stringify(body), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
}

