        console.log(`[directory] role ${owner.role} → ${verdict.owner.role} from the directory email=${ctx.email ?? owner.email ?? '∅'} siteKey=${siteKeyId}`);
      }
      owner = verdict.owner;
    }
  }

  // Delegated-design capability: a member whose role is listed in the portal
  // definition's `designRoles` may enter design mode. Resolved here so the
  // client gate has a single server-authored signal — the design write
  // endpoint (`PATCH /v1/cms-definitions/:id/design`) re-checks independently.
  const canDesign = !!(owner && cms?.designRoles?.length && cms.designRoles.includes(owner.role));

  const body: SiteKeyMeResponse = owner
    ? {
        isMember: true,
        role: owner.role,
        customProperties: owner.customProperties,
        email: owner.email ?? ctx.email,
        canDesign,
      }
    : { isMember: false, email: ctx.email };
  return new Response(JSON.stringify(body), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
}

