import { describe, expect, it, vi } from 'vitest';
import type { Env } from '../../types';
import type { AuthContext } from '../../permissions/types';

// GET /v1/site-key/memberships: the sites an SDK developer build's site switch offers.
const facts = vi.hoisted(() => ({
  owners: {
    user_george: [
      { siteKeyId: 'sk_demo', userId: 'user_george', role: 'manager', status: 'active' },
      { siteKeyId: 'sk_wac', userId: 'user_george', role: 'admin', status: 'active' },
      { siteKeyId: 'sk_blocked', userId: 'user_george', role: 'manager', status: 'blocked' },
      { siteKeyId: 'sk_off', userId: 'user_george', role: 'admin', status: 'active' },
      { siteKeyId: 'sk_web_only', userId: 'user_george', role: 'admin', status: 'active' },
      { siteKeyId: 'sk_wrap', userId: 'user_george', role: 'viewer', status: 'active' },
    ],
  } as Record<string, unknown[]>,
  sites: {
    sk_demo: { id: 'sk_demo', publishableKey: 'pk_demo', name: 'wac Demo', slug: 'wac-demo-wrap', enabled: true,
      cmsDefinitionId: 'cms_demo', allowedOrigins: ['https://wac-ios.app', 'https://demo.ripul.io'] },
    sk_wac: { id: 'sk_wac', publishableKey: 'pk_wac', name: 'WAC Business', slug: 'wac', enabled: true,
      cmsDefinitionId: 'cms_wac', allowedOrigins: ['*'] },
    sk_blocked: { id: 'sk_blocked', publishableKey: 'pk_blocked', name: 'Blocked', enabled: true, allowedOrigins: ['*'] },
    sk_off: { id: 'sk_off', publishableKey: 'pk_off', name: 'Off', enabled: false, allowedOrigins: ['*'] },
    sk_web_only: { id: 'sk_web_only', publishableKey: 'pk_web', name: 'Web only', enabled: true,
      cmsDefinitionId: 'cms_web', allowedOrigins: ['https://example.com'] },
    sk_wrap: { id: 'sk_wrap', publishableKey: 'pk_wrap', name: 'App key', enabled: true,
      delegateCmsDefinitionTo: 'sk_wac', allowedOrigins: ['*'] },
  } as Record<string, unknown>,
}));

vi.mock('../storage', async (importOriginal) => ({
  ...(await importOriginal<typeof import('../storage')>()),
  listSiteKeysForUser: vi.fn(async (userId: string) => facts.owners[userId] ?? []),
  getSiteKeyById: vi.fn(async (id: string) => facts.sites[id] ?? null),
}));

import { handleSiteKeyMemberships } from '../handlers';

const env = {} as Env;
const person = (userId: string, authSource: AuthContext['authSource'] = 'clerk_jwt') =>
  ({ authSource, userId, email: 'georgina@wac.rocks' } as AuthContext);
const names = async (response: Response) => ((await response.json()) as { sites: { name: string }[] }).sites.map(s => s.name);

describe('GET /v1/site-key/memberships', () => {
  it('lists active memberships on enabled keys, sorted, with what the SDK needs', async () => {
    const response = await handleSiteKeyMemberships(person('user_george'), env, null);
    expect(response.status).toBe(200);
    expect(response.headers.get('Cache-Control')).toBe('no-store');
    const { sites } = await response.json() as { sites: unknown[] };
    expect(sites).toEqual([
      { siteKeyId: 'sk_wrap', publishableKey: 'pk_wrap', name: 'App key', cmsDefinitionId: 'cms_wac', role: 'viewer' },
      { siteKeyId: 'sk_wac', publishableKey: 'pk_wac', name: 'WAC Business', slug: 'wac', cmsDefinitionId: 'cms_wac', role: 'admin' },
      { siteKeyId: 'sk_web_only', publishableKey: 'pk_web', name: 'Web only', cmsDefinitionId: 'cms_web', role: 'admin' },
      { siteKeyId: 'sk_demo', publishableKey: 'pk_demo', name: 'wac Demo', slug: 'wac-demo-wrap', cmsDefinitionId: 'cms_demo', role: 'manager' },
    ]);
  });

  it('leaves out blocked memberships and disabled keys', async () => {
    const listed = await names(await handleSiteKeyMemberships(person('user_george'), env, null));
    expect(listed).not.toContain('Blocked');
    expect(listed).not.toContain('Off');
  });

  it('keeps only keys that accept the app origin when one is given', async () => {
    const listed = await names(await handleSiteKeyMemberships(person('user_george'), env, 'https://wac-ios.app'));
    expect(listed).toEqual(['App key', 'WAC Business', 'wac Demo']);
  });

  it('lists nothing for a person with no memberships', async () => {
    expect(await names(await handleSiteKeyMemberships(person('user_nobody'), env, null))).toEqual([]);
  });

  it('refuses a site key or machine caller: only a person’s own Ripul sign-in counts', async () => {
    expect((await handleSiteKeyMemberships(person('user_george', 'site_key'), env, null)).status).toBe(403);
    expect((await handleSiteKeyMemberships(person('user_george', 'machine_token'), env, null)).status).toBe(403);
    expect((await handleSiteKeyMemberships(person('', 'clerk_jwt'), env, null)).status).toBe(403);
  });
});

