import SwiftUI

public extension Notification.Name {
    /// Scoped to the originating bridge so another embedded console cannot
    /// present or sign out the wrong account.
    static let ripulShowProfile = Notification.Name("ripulShowProfile")
    /// Asks the host to present `RipulSolutionsScreen`. Scoped to the
    /// originating bridge, same as the above. `SolutionsSheet` is the SDK's
    /// own listener; a host that wants its own presentation can observe this
    /// instead.
    static let ripulShowSolutions = Notification.Name("ripulShowSolutions")
}

/// The session list's overflow menu: new CLI sessions on the default machine,
/// new API chats pinned to a backend model, refresh, console logs.
///
/// A public component so a host that renders its own root chrome (the
/// first-party Agents|Plans shell) can offer the SAME menu the standalone
/// agent screen offers in its bar — one implementation, two chromes.
/// Extracted verbatim from RipulAgentScreen.sessionListMenuItems.
@available(iOS 26.0, macOS 26.0, *)
public struct SessionListMenu: View {
    /// Plain refs, NOT @ObservedObject: this view renders INSIDE an open
    /// Menu, where a direct invalidation re-resolves — and visibly flashes —
    /// the presented menu on every bridge/model publish (constant during a
    /// streaming turn). Body reads still see live values whenever the menu
    /// host legitimately re-resolves; the agent screen keys that via
    /// GlassTopBar.menuKey, which includes the machines roster this menu
    /// renders from.
    let bridge: AgentBridge
    let model: RipulSessionListModel
    let cache: RipulSessionCache
    /// Collapses the list when a new session opens, matching the list's own
    /// behavior. Write-only: the menu never reads the mode.
    let setShowingSessionList: (Bool) -> Void
    /// Raises the host's `NewSessionModelPicker`. Menu content can't present a
    /// sheet of its own, so the host owns the presentation and this only asks
    /// for it. Nil ⇒ the entry is omitted.
    let onShowModelPicker: (() -> Void)?
    let usesUnifiedCreation: Bool
    /// Offers the "Solutions" row, which asks the host to present
    /// `RipulSolutionsScreen` (see `SolutionsSheet`).
    ///
    /// Opt-in, and off by default, because the two menu hosts want opposite
    /// answers. The first-party app reaches Solutions from its sidebar, so a
    /// menu row there would be a second door to a screen that already has one.
    /// An SDK host has no sidebar and — since `f291beca3` moved Solutions out
    /// of the sessions list — no route at all; this is it. The agent screen
    /// turns it on exactly when the host supplied a
    /// `RipulSessionsConfiguration.solutionManagement`.
    let showsSolutions: Bool

    public init(
        bridge: AgentBridge,
        model: RipulSessionListModel,
        cache: RipulSessionCache,
        showingSessionList: Binding<Bool>,
        onShowModelPicker: (() -> Void)? = nil,
        usesUnifiedCreation: Bool = false,
        showsSolutions: Bool = false
    ) {
        self.bridge = bridge
        self.model = model
        self.cache = cache
        self.setShowingSessionList = { showingSessionList.wrappedValue = $0 }
        self.onShowModelPicker = onShowModelPicker
        self.usesUnifiedCreation = usesUnifiedCreation
        self.showsSolutions = showsSolutions
    }

    /// For a large host view: no `Binding` is made in the host's body, so the
    /// host doesn't observe the mode (see `RipulListMode`).
    public init(
        bridge: AgentBridge,
        model: RipulSessionListModel,
        cache: RipulSessionCache,
        listMode: RipulListMode,
        onShowModelPicker: (() -> Void)? = nil,
        usesUnifiedCreation: Bool = false,
        showsSolutions: Bool = false
    ) {
        self.bridge = bridge
        self.model = model
        self.cache = cache
        self.setShowingSessionList = { listMode.showingSessionList = $0 }
        self.onShowModelPicker = onShowModelPicker
        self.usesUnifiedCreation = usesUnifiedCreation
        self.showsSolutions = showsSolutions
    }

    private var defaultMachine: RemoteMachine? {
        let defaultMachineId = (cache.object(forKey: "ripulDefaultMachineId") as? String) ?? ""
        return model.machines.first { $0.machineId == defaultMachineId && $0.isOnline && !$0.isDisabled(cache: cache) }
    }

    public var body: some View {
        if !usesUnifiedCreation, let machine = defaultMachine {
            ForEach(ProviderConstants.cliProviders, id: \.id) { provider in
        }

        if bridge.audience == .developer && !model.usesDirectConnections {
            Button {
                NotificationCenter.default.post(name: .ripulShowProfile, object: bridge)
            } label: {
                Label("Profile", systemImage: "person.crop.circle")
            }
            .uiKitIdentifier("AgentScreen.listMenu.profile")

            Divider()
        }

        // Beside Profile: both are host-presented destinations rather than
        // session verbs. Gated on the developer audience like Profile is —
        // Solutions is the workbench behind a solution (collections, contexts,
        // the model catalog), and an end-user surface has no business in it.
        if showsSolutions && bridge.audience == .developer {
            Button {
                NotificationCenter.default.post(name: .ripulShowSolutions, object: bridge)
            } label: {
                Label("Solutions", systemImage: "slider.horizontal.3")
            }
            .uiKitIdentifier("AgentScreen.listMenu.solutions")

            Divider()
        }

        if !model.usesDirectConnections {
        Button {
            NotificationCenter.default.post(name: .ripulShowAppWorkingDirectory, object: bridge)
        } label: {
            Label("App Working Directory…", systemImage: "folder.badge.gearshape")
        }
        .uiKitIdentifier("AgentScreen.listMenu.appWorkingDirectory")
        }

        Divider()

        Button {
            Task { await model.refresh() }
        } label: {
            Label("Refresh", systemImage: "arrow.clockwise")
        }
        .uiKitIdentifier("AgentScreen.listMenu.refreshButton")

        Button {
            NotificationCenter.default.post(name: .ripulShowDevTools, object: nil)
        } label: {
            Label("Console Logs", systemImage: "doc.text.magnifyingglass")
        }
        .uiKitIdentifier("AgentScreen.listMenu.consoleLogsButton")
    }
}

