def executables(app):
    """Every Mach-O file in the bundle."""
    out = []
    for folder, _, files in os.walk(app):
        for name in files:
            path = os.path.join(folder, name)
            if os.path.islink(path):
                continue
            try:
                with open(path, "rb") as handle:
                    magic = handle.read(4)
            except OSError:
                continue
            if magic in (b"\xcf\xfa\xed\xfe", b"\xce\xfa\xed\xfe", b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf"):
                out.append(path)
    return out


def find_app(target, scratch):
    if target.endswith(".ipa"):
        with zipfile.ZipFile(target) as archive:
            archive.extractall(scratch)
        target = os.path.join(scratch, "Payload")
    if target.endswith(".app") and os.path.isdir(target):
        return target
    for folder, folders, _ in os.walk(target):
        for name in folders:
            if name.endswith(".app"):
                return os.path.join(folder, name)
    return None


def check_binary(register, target, allow_known):
    with tempfile.TemporaryDirectory() as scratch:
        app = find_app(target, scratch)
        if app is None:
            print(f"error: no .app in {target}", file=sys.stderr)
            sys.exit(2)
        files = executables(app)
        found = {}
        for path in files:
            data = subprocess.run(["strings", "-a", "-", path], capture_output=True).stdout
            for item in register["binary_names"]:
                if item["name"].encode() in data:
                    found.setdefault(item["name"], (item, []))[1].append(os.path.relpath(path, app))
    print(f"binary: {os.path.basename(app)}, {len(files)} executable file(s) read")
    failed = False
    never = [(item, where) for item, where in found.values() if item["tier"] == "never"]
    known = [(item, where) for item, where in found.values() if item["tier"] != "never"]
    if never:
        failed = True
        print(f"\nFAIL  {len(never)} developer-only name(s) are in this build. It was built as a developer build\n"
              "      (Debug, or with RIPUL_DEVELOPER_BUILD set). It must not be uploaded. There is no override.")
        for item, where in never:
            print(f"   {item['name']}  ({item['group']})  in {where[0]}")
    if known:
        verdict = "allowed (--allow-known)" if allow_known else "FAIL"
        print(f"\n{verdict}  {len(known)} known private name(s) are in this build:")
        for item, where in known:
            print(f"   {item['name']}  ({item['group']})  in {where[0]}")
        if not allow_known:
            failed = True
    if not found:
        print("   none of the registered names are in it")
    return failed


def main():
    arguments = [a for a in sys.argv[1:] if not a.startswith("--")]
    allow_known = "--allow-known" in sys.argv
    if not arguments or arguments[0] not in ("source", "binary", "all") \
            or (arguments[0] != "source" and len(arguments) < 2):
        print(__doc__)
        sys.exit(2)
    register = load_register()
    failed = False
    if arguments[0] in ("source", "all"):
        failed = check_source(register, allow_known) or failed
    if arguments[0] in ("binary", "all"):
        failed = check_binary(register, arguments[1], allow_known) or failed
    print()
    if failed:
        print("NOT CLEAN. See ripul-native-app/docs/app-store-private-apis.md")
        sys.exit(1)
    print("CLEAN for a tester build; known private uses remain (see above)." if allow_known
          else "CLEAN. Nothing private was found.")


if __name__ == "__main__":
    main()
