              "      (Debug, or with RIPUL_DEVELOPER_BUILD set). It must not be uploaded. There is no override.")
        for item, where in never:
            print(f"   {item['name']}  ({item['group']})  in {where[0]}")
    if known:
        verdict = "allowed (--allow-known)" if allow_known else "FAIL"
        print(f"\n{verdict}  {len(known)} known private name(s) are in this build:")
        for item, where in known:
            print(f"   {item['name']}  ({item['group']})  in {where[0]}")
        if not allow_known:
            failed = True
    if not found:
        print("   none of the registered names are in it")
    return failed


def main():
    arguments = [a for a in sys.argv[1:] if not a.startswith("--")]
    allow_known = "--allow-known" in sys.argv
    if not arguments or arguments[0] not in ("source", "binary", "all") \
            or (arguments[0] != "source" and len(arguments) < 2):
        print(__doc__)
        sys.exit(2)
    register = load_register()
    failed = False
    if arguments[0] in ("source", "all"):
        failed = check_source(register, allow_known) or failed
    if arguments[0] in ("binary", "all"):
        failed = check_binary(register, arguments[1], allow_known) or failed
    print()
    if failed:
        print("NOT CLEAN. See ripul-native-app/docs/app-store-private-apis.md")
        sys.exit(1)
    print("CLEAN for a tester build; known private uses remain (see above)." if allow_known
          else "CLEAN. Nothing private was found.")


if __name__ == "__main__":
    main()
