import UIKit
import SwiftUI
import RipulAgent

@MainActor
final class WACAgentCoordinator {

    private(set) var isVisible = false
    var onVisibilityChanged: ((Bool) -> Void)?

    private var hostingController: UIHostingController<WACAgentPanelView>?
    private weak var parentViewController: UIViewController?

    init(parentViewController: UIViewController) {
        self.parentViewController = parentViewController
        installHostingController()
    }

    // MARK: - Hosting Controller Setup

    private func installHostingController() {
        guard let parent = parentViewController else { return }

        let config = AgentConfiguration(
            baseURL: AgentConfiguration.defaultBaseURL,
            siteKey: RipulConfig.siteKey,
            hideHeader: true,
            hideTabSwitcher: true,
            hideChatInput: true,
            nativeChatInputHeight: 100
        )

        let panelView = WACAgentPanelView(
            configuration: config,
            onClose: { [weak self] in
                self?.hide()
            },
            linkOpenDelegate: self
        )

        let hosting = UIHostingController(rootView: panelView)
        hosting.view.backgroundColor = .clear

        parent.addChild(hosting)

        // Leave the tab bar visible so the user can navigate away
        let tabBarHeight = (parent as? UITabBarController)?.tabBar.frame.height ?? 0
        hosting.view.frame = CGRect(
            x: 0,
            y: 0,
            width: parent.view.bounds.width,
            height: parent.view.bounds.height - tabBarHeight
        )
        hosting.view.autoresizingMask = [.flexibleWidth, .flexibleHeight]

        // Start offscreen
        hosting.view.transform = CGAffineTransform(
            translationX: 0,
            y: UIScreen.main.bounds.height
        )

