#!/usr/bin/env python3
"""Refuses a TestFlight / App Store upload that still carries developer-only code.

  check_store_build.py <app|ipa|xcarchive>

Exit 0 when the build may be uploaded, 1 when it must not, 2 on a usage error.

Reads the strings in every Mach-O file of the app, the way Ripul's own
check_private_apis.py does, and looks for:

  refused   RIPUL_SITE_SWITCH_COMPILED_IN — the Ripul SDK's site switch
            (RipulSiteSwitch), compiled in by RIPUL_DEVELOPER_TOOLS,
            RIPUL_DEVELOPER_BUILD or DEBUG. A build with it can point Ripul at
            another site, so it never goes to TestFlight or the App Store.
            Also WAC's own dev-helper configuration (RipulDevConsoleConfig,
            com.wac.ripuldev), compiled in only by WAC_DEVELOPER_TOOLS.

  reported  The SDK's dev helper itself (RipulDevAssistantOverlay and its
            console). WAC compiles out every way to open it, but the SDK still
            compiles the code into every build: measured 21 Oct 2026 in a
            Release (prod) build. Reported, not refused, until the SDK compiles
            it out too; WAC_STRICT_DEV_HELPER=1 refuses it now.
"""
import os
import subprocess
import sys
import tempfile
import zipfile

REFUSED = {
    "RIPUL_SITE_SWITCH_COMPILED_IN": "the Ripul SDK's site switch (RIPUL_DEVELOPER_TOOLS)",
    "RipulDevConsoleConfig": "WAC's dev-helper configuration (WAC_DEVELOPER_TOOLS)",
    "com.wac.ripuldev": "WAC's dev-helper configuration (WAC_DEVELOPER_TOOLS)",
}
REPORTED = {
    "RipulDevAssistantOverlay": "the SDK's dev helper overlay",
    "RipulDevOverlayWindow": "the SDK's dev helper overlay",
    "RipulAgentConsole": "the SDK's developer console",
}
MACH_O = (b"\xcf\xfa\xed\xfe", b"\xce\xfa\xed\xfe", b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf")


def find_app(target, scratch):
    if target.endswith(".ipa"):
        with zipfile.ZipFile(target) as archive:
            archive.extractall(scratch)
        target = os.path.join(scratch, "Payload")
    if target.endswith(".app") and os.path.isdir(target):
        return target
    for folder, folders, _ in os.walk(target):
        for name in folders:
            if name.endswith(".app"):
                return os.path.join(folder, name)
    return None


def executables(app):
    out = []
    for folder, _, files in os.walk(app):
        for name in files:
            path = os.path.join(folder, name)
            if os.path.islink(path):
                continue
            try:
                with open(path, "rb") as handle:
                    if handle.read(4) in MACH_O:
                        out.append(path)
            except OSError:
                continue
    return out


def scan(target):
    """{name: [relative paths]} for every listed name found in the app."""
    with tempfile.TemporaryDirectory() as scratch:
        app = find_app(target, scratch)
        if app is None:
            print(f"error: no .app in {target}", file=sys.stderr)
            sys.exit(2)
        found = {}
        files = executables(app)
        for path in files:
            data = subprocess.run(["strings", "-a", "-", path], capture_output=True).stdout
            for name in (*REFUSED, *REPORTED):
